/* @lc app=leetcode id=3854 lang=kotlin */ class Solution { fun cand(nums: IntArray, p: Int): Pair<Int, Long> = nums.indices.partition { Math.floorMod(nums[it], 2) != (it + p) % 2 }.let { (bad, good) -> bad.map { nums[it].toLong() }.sorted().let { xs -> good.map { nums[it].toLong() }.let { fx -> (fx.minOrNull() ?: Long.MAX_VALUE / 4).let { fmin -> (fx.maxOrNull() ?: Long.MIN_VALUE / 4).let { fmax -> xs.size.let { m -> bad.size to (0..m).minOf { t -> maxOf(fmax, if (t > 0) xs[t - 1] + 1 else Long.MIN_VALUE / 4, if (t < m) xs[m - 1] - 1 else Long.MIN_VALUE / 4) - minOf(fmin, if (t > 0) xs[0] + 1 else Long.MAX_VALUE / 4, if (t < m) xs[t] - 1 else Long.MAX_VALUE / 4) } } } } } } } fun makeParityAlternating(nums: IntArray): IntArray = listOf(cand(nums, 0), cand(nums, 1)).let { c -> c.minOf { it.first }.let { mo -> intArrayOf(mo, c.filter { it.first == mo }.minOf { it.second }.toInt()) } } }